[
  {
    "statement": "Evidence-based, tree-removal techniques include group-selection harvesting, general logging/removal, partial retention harvesting, and clearcutting.",
    "citations": []
  },
  {
    "statement": "Group-selection harvesting increased understory plant cover and diversity in multiple studies.",
    "citations": [
      "1224"
    ]
  },
  {
    "statement": "Group-selection harvesting increased the density of young trees in multiple studies.",
    "citations": [
      "1224"
    ]
  },
  {
    "statement": "Some studies reported that group-selection harvesting caused decreases or had no effects on understory metrics and tree density or growth-rate.",
    "citations": [
      "1224"
    ]
  },
  {
    "statement": "General logging/removal increased understory plant density and cover in about half of studies.",
